  function getCatalogEventById(eventId) {
    if (eventId == null || eventId === "") return null;
    if (catalogById.has(eventId)) return catalogById.get(eventId);
    const stringId = String(eventId);
    if (catalogById.has(stringId)) return catalogById.get(stringId);
    const numericId = Number(stringId);
    if (Number.isSafeInteger(numericId) && catalogById.has(numericId)) {
      return catalogById.get(numericId);
    }
    return null;
  }

  function detectBrowserPerformanceProfile() {
    const nav = typeof navigator === "undefined" ? {} : navigator;
    const userAgent = String(nav.userAgent || "");
    const vendor = String(nav.vendor || "");
    const isEdge = /\bEdg\//.test(userAgent);
    const isFirefox = /\bFirefox\//.test(userAgent);
    const isOpera = /\bOPR\/|\bOpera\//.test(userAgent);
    const isSafari = /\bSafari\//.test(userAgent) && !/\bChrome\/|\bChromium\/|\bCriOS\/|\bFxiOS\//.test(userAgent);
    const isChrome = (/\bChrome\/|\bChromium\/|\bCriOS\//.test(userAgent) || /Google Inc/i.test(vendor)) && !isEdge && !isOpera;
    const deviceMemory = Number(nav.deviceMemory);
    const hardwareConcurrency = Number(nav.hardwareConcurrency);
    const constrainedDevice = (
      (Number.isFinite(deviceMemory) && deviceMemory > 0 && deviceMemory <= 4) ||
      (Number.isFinite(hardwareConcurrency) && hardwareConcurrency > 0 && hardwareConcurrency <= 4)
    );
    const leanVisuals = Boolean(isChrome || isFirefox || isSafari || constrainedDevice);
    return {
      engine: isEdge ? "edge" : isChrome ? "chrome" : isFirefox ? "firefox" : isSafari ? "safari" : "other",
      leanVisuals: leanVisuals,
      constrainedDevice: constrainedDevice,
      canvasDprCap: leanVisuals ? 1.5 : 2,
      desynchronizedCanvas: true,
      traceFrameBudgetMs: leanVisuals ? TRACE_PROGRESSIVE_COMPAT_FRAME_BUDGET_MS : TRACE_PROGRESSIVE_FRAME_BUDGET_MS,
      traceBatchSize: leanVisuals ? TRACE_PROGRESSIVE_COMPAT_BATCH_SIZE : TRACE_PROGRESSIVE_BATCH_SIZE,
      clusterChunkInterval: leanVisuals ? 48 : 100,
      clusterChunkDelay: leanVisuals ? 16 : 25,
    };
  }

  const BROWSER_PERFORMANCE_PROFILE = detectBrowserPerformanceProfile();

  function applyBrowserPerformanceProfile() {
    const root = document.documentElement;
    if (!root) return;
    root.dataset.browserEngine = BROWSER_PERFORMANCE_PROFILE.engine;
    root.classList.toggle("browser-perf-lean-visuals", Boolean(BROWSER_PERFORMANCE_PROFILE.leanVisuals));
    root.classList.toggle("browser-perf-constrained-device", Boolean(BROWSER_PERFORMANCE_PROFILE.constrainedDevice));
  }

  function canvasContextOptions(alpha) {
    const options = {
      alpha: alpha !== false,
    };
    if (!options.alpha && BROWSER_PERFORMANCE_PROFILE.desynchronizedCanvas) {
      options.desynchronized = true;
    }
    return options;
  }

  function getCanvas2dContext(canvas, options) {
    if (!canvas || typeof canvas.getContext !== "function") return null;
    try {
      return canvas.getContext("2d", options || canvasContextOptions(true));
    } catch (error) {
      return canvas.getContext("2d");
    }
  }

  function renderCanvasDevicePixelRatio() {
    return Math.min(window.devicePixelRatio || 1, BROWSER_PERFORMANCE_PROFILE.canvasDprCap);
  }

