  function defaultResearchCategoryVisibilityState(additionalCategories) {
    const categories = LEGEND_CONTROLS.uniqueKeys(
      Object.keys(RESEARCH_SITE_CATEGORY_LABELS).concat(
        Array.isArray(additionalCategories) ? additionalCategories : []
      )
    );
    return categories.reduce(function (visibility, category) {
      visibility[category] = true;
      return visibility;
    }, {});
  }

