    runtime.traceSequenceCacheValue = null;
    runtime.traceRenderCacheKey = "";
    runtime.traceRenderCacheValue = null;
    runtime.traceRenderCacheFacilityStats = null;
    runtime.packedTraceRenderCacheKey = "";
    runtime.packedTraceRenderCacheValue = null;
    runtime.packedStaticTraceRenderCache.clear();
